insert into public.topics (module_id, slug, title, summary, position, published) select id, 'state-and-hooks', 'State and Hooks', 'UseState and useEffect, and the rules of hooks.', 0, true from public.modules where level_id = 2 and title = 'React' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain state and hooks in your own words.","Recognise and apply: state is data a component owns and re-renders when it changes.","Recognise and apply: hooks must be called at the top level of a component, never inside conditions.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers state and hooks: useState and useEffect, and the rules of hooks. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that state is data a component owns and re-renders when it changes. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that hooks must be called at the top level of a component, never inside conditions. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how state and hooks fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'import { useState, useEffect } from ''react'';
