insert into public.topics (module_id, slug, title, summary, position, published) select id, 'next-js-fundamentals', 'Next.js Fundamentals', 'The App Router, server vs client components, and rendering choices.', 0, true from public.modules where level_id = 3 and title = 'Advanced JS, TypeScript & Next.js' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain next.js fundamentals in your own words.","Recognise and apply: server components run on the server and can read the database directly.","Recognise and apply: client components (\"use client\") run in the browser for interactivity.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers next.js fundamentals: the App Router, server vs client components, and rendering choices. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that server components run on the server and can read the database directly. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that client components (\"use client\") run in the browser for interactivity. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how next.js fundamentals fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'typescript', '// Server component (default): fetches data, renders HTML.
insert into public.quizzes (topic_id, pass_mark) select id, 7 from public.topics where slug = 'next-js-fundamentals' on conflict (topic_id) do nothing;